import{at as e,it as t,n,vt as r}from"./chunks/framework.B6nQ8gjX.js";var i=JSON.parse(`{"title":"Tool reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/tools.md","filePath":"reference/tools.md","lastUpdated":1795608830000}`),a={name:`reference/tools.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="tool-reference" tabindex="-1">Tool reference <a class="header-anchor" href="#tool-reference" aria-label="Permalink to “Tool reference”">​</a></h1><p>All 18 tools: 11 read, 7 write. With <code>CARDDAV_READ_ONLY=true</code> the write tools are not registered at all — they do not appear in <code>tools/list</code>.</p><p>All 18 are registered unless you say otherwise. <code>CARDDAV_ALLOW_TOOLS</code> and <code>CARDDAV_DENY_TOOLS</code> narrow the list to the ones you want, and <code>CARDDAV_ALLOW_TOOLS=essential</code> selects the 6 marked <strong>essential</strong> below — see <a href="/guide/configuration#choosing-the-tools-that-load">choosing the tools that load</a>.</p><p>👤 marks a tool that <strong>asks a person</strong> before it acts, through MCP elicitation — a dialog the model cannot answer on its behalf. Where the client cannot show one, it falls back to a two-call <code>confirm_token</code> bound to the exact target and expiring after five minutes, and says which of the two it was. <code>ELICITATION=false</code> takes that fallback deliberately; it never removes the guard. See <a href="/guide/approval">Asking a person</a>.</p><p>Every tool declares all four MCP annotations — <code>readOnlyHint</code>, <code>destructiveHint</code>, <code>idempotentHint</code>, <code>openWorldHint</code>. They are a hint a client may ignore; the dialog is enforced here and cannot be, which is why the two lists are not the same one.</p><p>Every tool also declares an <code>outputSchema</code> and answers in both channels at once — the same object as <code>structuredContent</code>, and as JSON in a text block. Every answer built from address book content additionally carries <code>untrusted: true</code> and <code>source: &quot;carddav&quot;</code> as <strong>fields</strong>, so a client can check rather than notice. Two tools deliberately do not: <code>get_server_info</code> and <code>list_changes</code> return this server&#39;s own words — protocol tokens, ids and counts, with no card content in them at all. A marker on everything would be a marker on nothing.</p><h2 id="read-tools" tabindex="-1">Read tools <a class="header-anchor" href="#read-tools" aria-label="Permalink to “Read tools”">​</a></h2><h3 id="list-address-books" tabindex="-1"><code>list_address_books</code> <a class="header-anchor" href="#list-address-books" aria-label="Permalink to “list_address_books”">​</a></h3><p><strong>List the address books</strong> — read-only, <strong>essential</strong></p><p>Every address book this server may use, with the id to pass to the other tools. Always asks the server rather than answering from a cache — being current is this tool’s whole job.</p><p>Takes no parameters.</p><h3 id="get-server-info" tabindex="-1"><code>get_server_info</code> <a class="header-anchor" href="#get-server-info" aria-label="Permalink to “get_server_info”">​</a></h3><p><strong>What the connected CardDAV server can do</strong> — read-only</p><p>Reports the DAV compliance tokens, which vCard versions each address book accepts, and whether the optional features this server relies on actually work here. The first thing to run when something behaves differently than expected — CardDAV implementations differ more than the specification suggests.</p><p>Takes no parameters.</p><h3 id="list-contacts" tabindex="-1"><code>list_contacts</code> <a class="header-anchor" href="#list-contacts" aria-label="Permalink to “list_contacts”">​</a></h3><p><strong>List contacts</strong> — read-only, <strong>essential</strong></p><p>Contacts in one or more address books, as short summaries: name, organisation, title, email addresses, phone numbers, categories, birthday, anniversary, and whether a photo is present. <code>include</code> adds urls, addresses or messaging handles. Only these properties are fetched, so this stays cheap on a large address book — get_contact returns the whole card. Sorted by name; <code>offset</code> pages.</p><p>The answer carries <code>total</code>, the number of contacts before <code>limit</code> and <code>offset</code>, and a note naming the <code>offset</code> of the next page when it was cut short.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>address_books</code></td><td>string[]</td><td>no</td><td>Which address books to look in. Leave it out for every address book this server may see.</td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>How many entries to return. Defaults to CARDDAV_MAX_CONTACTS, at most 500.</td></tr><tr><td><code>offset</code></td><td>integer</td><td>no</td><td>Entries to skip, for the next page. Results are sorted by name, so offset=limit continues where the previous call stopped.</td></tr><tr><td><code>include</code></td><td><code>&quot;urls&quot;</code> | <code>&quot;addresses&quot;</code> | <code>&quot;impp&quot;</code> | <code>&quot;all&quot;</code>[]</td><td>no</td><td>Extra properties per contact, which cost context. Names, organisation, title, emails, phones, categories, birthday and anniversary are always there. get_contact has the rest.</td></tr><tr><td><code>include_groups</code></td><td>boolean</td><td>no</td><td>Include group cards in the listing. Off by default: a group is a vCard like any other, and mixing them into a contact list is usually not what was meant. list_groups reads them properly.</td></tr></tbody></table><h3 id="get-contact" tabindex="-1"><code>get_contact</code> <a class="header-anchor" href="#get-contact" aria-label="Permalink to “get_contact”">​</a></h3><p><strong>Read one contact in full</strong> — read-only, <strong>essential</strong></p><p>The complete card behind an id: every address, every phone number, the note, the birthday, and the names of any properties this server does not model. The free text comes back inside a fence marking it as somebody else’s writing.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from list_contacts, search_contacts, list_groups or list_changes.</td></tr></tbody></table><h3 id="search-contacts" tabindex="-1"><code>search_contacts</code> <a class="header-anchor" href="#search-contacts" aria-label="Permalink to “search_contacts”">​</a></h3><p><strong>Find contacts</strong> — read-only, <strong>essential</strong></p><p>Finds contacts. Two ways to say what you want, usable together.</p><p><code>query</code> is plain words. Every word must appear somewhere in <code>fields</code> (a name, organisation, email address or phone number by default), so &quot;laura meier&quot; finds a card stored as &quot;Meier Laura&quot;. Matching is case-insensitive and ignores invisible characters.</p><p><code>where</code> is exact conditions on named vCard properties — <code>BDAY</code>, <code>URL</code>, <code>TITLE</code>, <code>NOTE</code> and every other property the server names. A contact matches when <strong>all</strong> of <code>all</code> match, <strong>at least one</strong> of <code>any</code> matches and <strong>none</strong> of <code>none</code> match. Each condition is <code>{field, op, value}</code>; <code>op</code> is <code>contains</code>, <code>equals</code>, <code>starts_with</code>, <code>ends_with</code>, <code>exists</code> or <code>missing</code> (the last two take no value).</p><div class="language-json" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">{ </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;where&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: { </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;all&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: [{ </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;field&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;TITLE&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;op&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;contains&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;value&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;lead&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> }],</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">             &quot;none&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: [{ </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;field&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;URL&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;op&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;exists&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> }] } }</span></span></code></pre></div><p>A date is compared as digits, so <code>{&quot;field&quot;: &quot;BDAY&quot;, &quot;op&quot;: &quot;contains&quot;, &quot;value&quot;: &quot;0415&quot;}</code> finds 15 April whether the card says <code>19900415</code>, <code>1990-04-15</code>, <code>--0415</code> or <code>--04-15</code>. For &quot;who has a birthday soon&quot;, use <code>upcoming_dates</code> instead.</p><p>What CardDAV can express is sent to the server — one request per address book, with <code>allof</code> or <code>anyof</code>, <code>is-not-defined</code> and the match type. What it cannot (a negation, a date comparison, an AND of ORs) is finished here, and the whole result is checked again either way, because some servers filter only partially. <code>matched_with</code> says which happened:</p><ul><li><code>server-filter</code> — the server did exactly what was asked.</li><li><code>server-prefilter</code> — the server narrowed the request to a superset and the rest was finished here.</li><li><code>client-filter</code> — nothing could be narrowed (or the server cannot filter), so every card was fetched and matched here.</li></ul><p>Results are sorted by name; <code>total</code> is the number that matched before <code>limit</code> and <code>offset</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>query</code></td><td>string</td><td>no</td><td>Words to look for, matched case-insensitively. Every word must match somewhere in <code>fields</code>. Up to 8 words.</td></tr><tr><td><code>fields</code></td><td>vCard property[]</td><td>no</td><td>Which vCard properties <code>query</code> is matched against. Defaults to FN, NICKNAME, EMAIL, TEL and ORG — the fields somebody searches by.</td></tr><tr><td><code>where</code></td><td>object</td><td>no</td><td><code>{all?, any?, none?}</code>, each a list of up to 20 conditions in total. See above.</td></tr><tr><td><code>address_books</code></td><td>string[]</td><td>no</td><td>Which address books to look in. Leave it out for every address book this server may see.</td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>How many entries to return. Defaults to CARDDAV_MAX_CONTACTS, at most 500.</td></tr><tr><td><code>offset</code></td><td>integer</td><td>no</td><td>Entries to skip, for the next page.</td></tr><tr><td><code>include</code></td><td><code>&quot;urls&quot;</code> | <code>&quot;addresses&quot;</code> | <code>&quot;impp&quot;</code> | <code>&quot;all&quot;</code>[]</td><td>no</td><td>Extra properties per contact.</td></tr></tbody></table><p>At least one of <code>query</code> and <code>where</code> is required.</p><h3 id="upcoming-dates" tabindex="-1"><code>upcoming_dates</code> <a class="header-anchor" href="#upcoming-dates" aria-label="Permalink to “upcoming_dates”">​</a></h3><p><strong>Upcoming birthdays and anniversaries</strong> — read-only</p><p>Birthdays and anniversaries that fall inside a window of days, sorted by date, with the age or the number of years where the card states a year. It does the calendar arithmetic, because CardDAV has no date filter and a model gets &quot;the next 7 days across a month end&quot; wrong: month and year ends are handled, and 29 February is observed on 28 February in a year without one, with <code>shifted_from: &quot;02-29&quot;</code> saying so.</p><p><code>days</code> counts calendar days starting at <code>from</code>, so <code>days: 1</code> is that one day and <code>days: 7</code> is the coming week. &quot;Today&quot; is read in the server&#39;s own time zone (<code>TZ</code>), which the answer names. A year of 1604 or 0 is a placeholder some clients write for &quot;no year&quot; and is not reported as one.</p><p>Only cards that have the date at all are fetched from the server; the rest is computed here.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>from</code></td><td>string</td><td>no</td><td>First day: &quot;today&quot; (the default) or YYYY-MM-DD.</td></tr><tr><td><code>days</code></td><td>integer</td><td>no</td><td>Calendar days in the window, counting <code>from</code> itself. Default 7, at most 366.</td></tr><tr><td><code>to</code></td><td>string</td><td>no</td><td>Last day, YYYY-MM-DD, instead of <code>days</code>.</td></tr><tr><td><code>kinds</code></td><td><code>&quot;birthday&quot;</code> | <code>&quot;anniversary&quot;</code>[]</td><td>no</td><td>Both, by default.</td></tr><tr><td><code>address_books</code></td><td>string[]</td><td>no</td><td>Which address books to look in.</td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>How many events to return.</td></tr><tr><td><code>offset</code></td><td>integer</td><td>no</td><td>Events to skip, for the next page.</td></tr></tbody></table><h3 id="get-contact-photo" tabindex="-1"><code>get_contact_photo</code> <a class="header-anchor" href="#get-contact-photo" aria-label="Permalink to “get_contact_photo”">​</a></h3><p><strong>Fetch a contact’s photo</strong> — read-only</p><p>Returns the photo stored on a card as an image. Only a photo embedded in the card itself — one stored as a link is reported by get_contact and never fetched, because that address was chosen by whoever wrote the card. The media type is decided from the bytes, never from what the card claims: JPEG, PNG, GIF and WebP are handed over, and bytes that are none of those are refused with a sentence rather than delivered under a generic label.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from list_contacts, search_contacts, list_groups or list_changes.</td></tr></tbody></table><h3 id="export-contacts" tabindex="-1"><code>export_contacts</code> <a class="header-anchor" href="#export-contacts" aria-label="Permalink to “export_contacts”">​</a></h3><p><strong>Export contacts as vCard text</strong> — read-only</p><p>The raw vCard text of one or more contacts, exactly as stored. The only way to see a property this server does not model, and the only way to take a backup of an address book from here.</p><p>This is the one tool whose two channels differ on purpose. <code>structuredContent</code> carries the cards byte for byte — that is the backup. The text block is a rendering of the same cards for reading, inside the nonce fence with every line datamarked: invisible characters are removed and markdown image markers are broken there, so a <code>NOTE</code> carrying <code>![…](https://…)</code> cannot make a client fetch a URL when it renders the answer. The first line of the text block says so. Injection shapes found in the exported cards are reported as a warning above the fence.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>ids</code></td><td>string[]</td><td>no</td><td>Specific contacts. Leave out to export a whole book.</td></tr><tr><td><code>address_book</code></td><td>string</td><td>no</td><td>Export every card in this address book.</td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>How many entries to return. Defaults to CARDDAV_MAX_CONTACTS, at most 500.</td></tr></tbody></table><h3 id="list-changes" tabindex="-1"><code>list_changes</code> <a class="header-anchor" href="#list-changes" aria-label="Permalink to “list_changes”">​</a></h3><p><strong>What changed in an address book</strong> — read-only</p><p>Cards created, changed or deleted since a sync token, using RFC 6578. Call it once without a token to get the current token, then again later with it. Not every server implements this — get_server_info reports whether this one does.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>address_book</code></td><td>string</td><td>yes</td><td>An address book id from list_address_books — its collection path. A full URL or the final path segment work too.</td></tr><tr><td><code>sync_token</code></td><td>string</td><td>no</td><td>The token from a previous call. Left out, this returns the current token and every card, which is the initial sync.</td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>How many entries to return. Defaults to CARDDAV_MAX_CONTACTS, at most 500.</td></tr></tbody></table><h3 id="list-groups" tabindex="-1"><code>list_groups</code> <a class="header-anchor" href="#list-groups" aria-label="Permalink to “list_groups”">​</a></h3><p><strong>List contact groups</strong> — read-only</p><p>Groups in one or more address books, with how many members each has. The members themselves are not resolved here — that is one extra request per book, and get_group is where a caller has said they want the names.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>address_books</code></td><td>string[]</td><td>no</td><td>Which address books to look in. Leave it out for every address book this server may see.</td></tr><tr><td><code>limit</code></td><td>integer</td><td>no</td><td>How many entries to return. Defaults to CARDDAV_MAX_CONTACTS, at most 500.</td></tr></tbody></table><h3 id="get-group" tabindex="-1"><code>get_group</code> <a class="header-anchor" href="#get-group" aria-label="Permalink to “get_group”">​</a></h3><p><strong>Read one group, with its members</strong> — read-only</p><p>A group card and the contacts in it, resolved to names and ids where the members live in the same address book. A member this server cannot resolve is still reported, as the reference the card holds.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from list_contacts, search_contacts, list_groups or list_changes.</td></tr></tbody></table><h2 id="write-tools" tabindex="-1">Write tools <a class="header-anchor" href="#write-tools" aria-label="Permalink to “Write tools”">​</a></h2><h3 id="create-contact" tabindex="-1"><code>create_contact</code> <a class="header-anchor" href="#create-contact" aria-label="Permalink to “create_contact”">​</a></h3><p><strong>Add a contact</strong> — write, <strong>essential</strong></p><p>Adds a card to an address book. The UID and the file name are generated here. The vCard version follows what the address book accepts — 3.0 unless it says otherwise, because that is what phones and desktop clients read completely.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>address_book</code></td><td>string</td><td>yes</td><td>An address book id from list_address_books — its collection path. A full URL or the final path segment work too.</td></tr><tr><td><code>formatted_name</code></td><td>unknown</td><td>no</td><td>FN, the display name. Derived from the name parts when left out on create. Null removes it, which no valid card may be without.</td></tr><tr><td><code>given_name</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>family_name</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>additional_names</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>name_prefix</code></td><td>unknown</td><td>no</td><td>Dr, Prof.</td></tr><tr><td><code>name_suffix</code></td><td>unknown</td><td>no</td><td>Jr, PhD.</td></tr><tr><td><code>nickname</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>organization</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>department</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>title</code></td><td>unknown</td><td>no</td><td>Job title.</td></tr><tr><td><code>role</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>emails</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>phones</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>urls</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>instant_messaging</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>addresses</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>birthday</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>anniversary</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>note</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>categories</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>raw_vcard</code></td><td>string</td><td>no</td><td>A complete vCard to store as-is, instead of the fields above. For properties this server does not model.</td></tr></tbody></table><h3 id="update-contact-👤" tabindex="-1"><code>update_contact</code> 👤 <a class="header-anchor" href="#update-contact-👤" aria-label="Permalink to “update_contact 👤”">​</a></h3><p><strong>Change a contact</strong> — write, destructive, <strong>essential</strong></p><p>Changes the fields named and leaves everything else exactly as it was — including properties this server does not model. Guarded by the card’s ETag, so a change made elsewhere in the meantime is refused rather than overwritten. A CardDAV server keeps no version history, so a person is asked first.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from list_contacts, search_contacts, list_groups or list_changes.</td></tr><tr><td><code>formatted_name</code></td><td>unknown</td><td>no</td><td>FN, the display name. Derived from the name parts when left out on create. Null removes it, which no valid card may be without.</td></tr><tr><td><code>given_name</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>family_name</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>additional_names</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>name_prefix</code></td><td>unknown</td><td>no</td><td>Dr, Prof.</td></tr><tr><td><code>name_suffix</code></td><td>unknown</td><td>no</td><td>Jr, PhD.</td></tr><tr><td><code>nickname</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>organization</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>department</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>title</code></td><td>unknown</td><td>no</td><td>Job title.</td></tr><tr><td><code>role</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>emails</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>phones</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>urls</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>instant_messaging</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>addresses</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>birthday</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>anniversary</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>note</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>categories</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>raw_vcard</code></td><td>string</td><td>no</td><td>Replace the whole card with this one. Unlike the named fields, this does not merge — anything not in it is gone.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only for a client that cannot show a dialog: the token from this tool’s own previous refusal, quoted back to confirm.</td></tr></tbody></table><h3 id="delete-contact-👤" tabindex="-1"><code>delete_contact</code> 👤 <a class="header-anchor" href="#delete-contact-👤" aria-label="Permalink to “delete_contact 👤”">​</a></h3><p><strong>Delete a contact</strong> — write, destructive</p><p>Removes a card. Cannot be undone — a CardDAV server has no trash and no version history. Guarded by the card’s ETag, so a card changed since it was read is refused rather than deleted blind. A group card is refused, before anybody is asked: <code>delete_group</code> is the tool for that, and the two stay separable in <code>CARDDAV_DENY_TOOLS</code> only because this one cannot reach a group.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from list_contacts, search_contacts, list_groups or list_changes.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only for a client that cannot show a dialog: the token from this tool’s own previous refusal, quoted back to confirm.</td></tr></tbody></table><h3 id="move-contact-👤" tabindex="-1"><code>move_contact</code> 👤 <a class="header-anchor" href="#move-contact-👤" aria-label="Permalink to “move_contact 👤”">​</a></h3><p><strong>Move a contact to another address book</strong> — write, destructive</p><p>Copies a card into another address book and removes it from the first. The id changes, because an id names a card in a collection. There is no transaction behind this: the copy is verified before the original is removed.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from list_contacts, search_contacts, list_groups or list_changes.</td></tr><tr><td><code>destination</code></td><td>string</td><td>yes</td><td>The address book to move the card into.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only for a client that cannot show a dialog: the token from this tool’s own previous refusal, quoted back to confirm.</td></tr></tbody></table><h3 id="create-group" tabindex="-1"><code>create_group</code> <a class="header-anchor" href="#create-group" aria-label="Permalink to “create_group”">​</a></h3><p><strong>Create a contact group</strong> — write</p><p>Creates a group card and puts the named contacts in it. The convention follows whatever groups the address book already uses, because a group written the other way is invisible in the client the person is actually looking at.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>address_book</code></td><td>string</td><td>yes</td><td>An address book id from list_address_books — its collection path. A full URL or the final path segment work too.</td></tr><tr><td><code>name</code></td><td>string</td><td>yes</td><td>The group’s display name.</td></tr><tr><td><code>note</code></td><td>string</td><td>no</td><td></td></tr><tr><td><code>members</code></td><td>string[]</td><td>no</td><td>Contact ids to put in the group.</td></tr></tbody></table><h3 id="update-group-👤" tabindex="-1"><code>update_group</code> 👤 <a class="header-anchor" href="#update-group-👤" aria-label="Permalink to “update_group 👤”">​</a></h3><p><strong>Rename a group or change who is in it</strong> — write, destructive</p><p>Changes a group’s name or note, and adds or removes members. Removing a member removes the grouping only — the contact itself is untouched. A CardDAV server keeps no version history, so a person is asked first.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from list_contacts, search_contacts, list_groups or list_changes.</td></tr><tr><td><code>name</code></td><td>string</td><td>no</td><td></td></tr><tr><td><code>note</code></td><td>unknown</td><td>no</td><td></td></tr><tr><td><code>add_members</code></td><td>string[]</td><td>no</td><td></td></tr><tr><td><code>remove_members</code></td><td>string[]</td><td>no</td><td></td></tr><tr><td><code>set_members</code></td><td>string[]</td><td>no</td><td>Replace the membership outright with exactly these contacts. Cannot be combined with add_members or remove_members.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only for a client that cannot show a dialog: the token from this tool’s own previous refusal, quoted back to confirm.</td></tr></tbody></table><h3 id="delete-group-👤" tabindex="-1"><code>delete_group</code> 👤 <a class="header-anchor" href="#delete-group-👤" aria-label="Permalink to “delete_group 👤”">​</a></h3><p><strong>Delete a contact group</strong> — write, destructive</p><p>Removes a group card. The contacts that were in it are not touched — only the grouping goes. Cannot be undone.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>yes</td><td>An id from list_contacts, search_contacts, list_groups or list_changes.</td></tr><tr><td><code>confirm_token</code></td><td>string</td><td>no</td><td>Only for a client that cannot show a dialog: the token from this tool’s own previous refusal, quoted back to confirm.</td></tr></tbody></table>`,92)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};